import { credentials, Metadata, type ServiceError, status } from '@grpc/grpc-js';
import {
  TrackingServiceClient,
  type Parcel,
  type WatchParcelResponse,
} from './generated/parcelflow/tracking/v1/tracking';

/** Result of a unary call: either a parcel or a gRPC error, so tests can assert both without try/catch. */
export type GrpcResult<T> = { ok: true; value: T } | { ok: false; code: status; details: string };

/**
 * Promise-based wrapper over the client generated by ts-proto from proto/parcelflow/tracking/v1.
 * Sends the test workspace in metadata, the same way the REST client sends the X-Workspace header.
 */
export class TrackingGrpcClient {
  private readonly client: TrackingServiceClient;
  private readonly metadata = new Metadata();

  constructor(address: string, workspace: string) {
    this.client = new TrackingServiceClient(address, credentials.createInsecure());
    this.metadata.set('x-workspace', workspace);
  }

  getParcel(trackingNumber: string): Promise<GrpcResult<Parcel>> {
    return new Promise((resolve) => {
      this.client.getParcel({ trackingNumber }, this.metadata, (error, response) => {
        resolve(error ? toError(error) : { ok: true, value: response.parcel! });
      });
    });
  }

  /**
   * Opens WatchParcel and collects updates. `next(n)` waits until n messages have arrived,
   * `end()` waits for the server to close the stream.
   */
  watchParcel(trackingNumber: string, timeoutMs = 5_000): ParcelWatch {
    const stream = this.client.watchParcel({ trackingNumber }, this.metadata, {
      deadline: Date.now() + timeoutMs,
    });
    return new ParcelWatch(stream);
  }

  close(): void {
    this.client.close();
  }
}

export class ParcelWatch {
  readonly updates: Parcel[] = [];
  private readonly done: Promise<GrpcResult<Parcel[]>>;
  private waiters: Array<() => void> = [];

  constructor(private readonly stream: NodeJS.ReadableStream & { cancel(): void }) {
    stream.on('data', (message: WatchParcelResponse) => {
      this.updates.push(message.parcel!);
      this.waiters.forEach((wake) => wake());
    });
    this.done = new Promise((resolve) => {
      stream.on('error', (error: ServiceError) => resolve(toError(error)));
      stream.on('end', () => resolve({ ok: true, value: this.updates }));
    });
  }

  /** Resolves once at least `count` updates are received. */
  async next(count: number): Promise<Parcel[]> {
    while (this.updates.length < count) {
      const ended = await Promise.race([
        new Promise<false>((wake) => this.waiters.push(() => wake(false))),
        this.done.then(() => true),
      ]);
      this.waiters = [];
      if (ended && this.updates.length < count) {
        throw new Error(`Stream ended after ${this.updates.length} updates, expected ${count}`);
      }
    }
    return this.updates.slice(0, count);
  }

  end(): Promise<GrpcResult<Parcel[]>> {
    return this.done;
  }

  cancel(): void {
    this.stream.cancel();
  }
}

/** Returns the value of a successful call, fails with the gRPC status otherwise. Keeps tests free of branches. */
export function unwrap<T>(result: GrpcResult<T>): T {
  if (!result.ok) throw new Error(`gRPC call failed: ${status[result.code]} ${result.details}`);
  return result.value;
}

function toError(error: ServiceError): GrpcResult<never> {
  return { ok: false, code: error.code, details: error.details };
}
